        if(mc.objectMouseOver!=null){record.put("rayHit",mc.objectMouseOver.hitVec==null?"null":mc.objectMouseOver.hitVec.toString());record.put("rayBlock",String.valueOf(mc.objectMouseOver.getBlockPos()));if(mc.objectMouseOver.hitInfo instanceof ArmPayloadHarvest.Target)record.put("rayPayloadCell",((ArmPayloadHarvest.Target)mc.objectMouseOver.hitInfo).cell.toString());}
        record.put("camera",new double[]{camera.posX,camera.posY,camera.posZ,camera.rotationYaw,camera.rotationPitch});record.put("fov",mc.gameSettings.fovSetting);record.put("root",expectedRoot.toString());record.put("rootSection",section.toString());record.put("rootSectionAdmitted",rootSectionAdmitted);record.put("rootRenderBounds",arm.getRenderBoundingBox().toString());record.put("phase",arm.progress());record.put("mode",arm.mode().name());record.put("operational",arm.isOperational());record.put("ownershipJournal",arm.payload()!=null&&arm.payload().hasOwnershipJournal());record.put("renderTransfer",arm.coreRenderTransfer==null?"null":arm.coreRenderTransfer.write().toString());
