    /** Independent homogeneous six-plane clipping of the actual submitted BODY quads. */
    private static int clippedTriangles(float[] vertices,Matrix4f view,Matrix4f projection,double x,double y,double z){
        if(vertices==null)return 0;int triangles=0;
        for(int at=0;at+11<vertices.length;at+=12){List<double[]> polygon=new ArrayList<>();for(int v=0;v<4;v++){int p=at+v*3;Vector4f point=Matrix4f.transform(view,new Vector4f((float)(vertices[p]-x),(float)(vertices[p+1]-y),(float)(vertices[p+2]-z),1),null);point=Matrix4f.transform(projection,point,null);polygon.add(new double[]{point.x,point.y,point.z,point.w});}
            for(int plane=0;plane<6&&!polygon.isEmpty();plane++){List<double[]> clipped=new ArrayList<>();double[] previous=polygon.get(polygon.size()-1);double before=distance(previous,plane);for(double[] next:polygon){double after=distance(next,plane);if((before>=0)!=(after>=0)){double t=before/(before-after);double[] cross=new double[4];for(int c=0;c<4;c++)cross[c]=previous[c]+t*(next[c]-previous[c]);clipped.add(cross);}if(after>=0)clipped.add(next);previous=next;before=after;}polygon=clipped;}
            if(polygon.size()<3)continue;double area=0;for(int i=0;i<polygon.size();i++){double[] a=polygon.get(i),b=polygon.get((i+1)%polygon.size());if(a[3]<=1e-9||b[3]<=1e-9)continue;area+=a[0]/a[3]*b[1]/b[3]-b[0]/b[3]*a[1]/a[3];}if(Math.abs(area)>1e-8)triangles+=polygon.size()-2;
        }return triangles;
    }
    private static double distance(double[] point,int plane){return point[3]+((plane&1)==0?point[plane/2]:-point[plane/2]);}
